:root {
--ink:#fff9f1;--muted:#d5c9e8;--pink:#ff679a;--orange:#ffbd73;--glass:rgba(38,28,69,.55)}
* {
box-sizing:border-box}
html,body {
margin:0;width:100%;height:100%;overflow:hidden;background:#261b4d;color:var(--ink);font-family:'DM Sans',sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}
#game {
position:fixed;inset:0}
canvas {
display:block;width:100%;height:100%;touch-action:none}
#vignette {
position:fixed;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(37,22,71,.34),transparent 25%,transparent 68%,rgba(28,24,61,.38));z-index:2}
.hud {
position:fixed;inset:0;pointer-events:none;z-index:3;padding:calc(env(safe-area-inset-top) + 18px) 20px calc(env(safe-area-inset-bottom) + 18px);display:none}
.hud.active {
display:flex;flex-direction:column;justify-content:space-between}
.topbar {
display:flex;align-items:flex-start;justify-content:space-between}
.brand-small {
font:700 13px 'Space Grotesk';letter-spacing:.23em;text-shadow:0 2px 12px #292044}
.metrics {
display:flex;gap:8px}
.pill {
min-width:74px;padding:8px 12px;border:1px solid rgba(255,255,255,.2);background:rgba(42,30,73,.48);backdrop-filter:blur(12px);border-radius:14px;text-align:center;box-shadow:0 8px 28px #20152b33}
.pill span {
display:block;font-size:9px;letter-spacing:.15em;color:#e3d8f4;font-weight:700}
.pill strong {
display:block;font:700 18px 'Space Grotesk';margin-top:1px}
.distance {
text-align:right;font-size:10px;letter-spacing:.12em;color:#f1d9e2;margin-top:8px;text-shadow:0 2px 8px #2b1944}
.bottom-hud {
display:flex;justify-content:space-between;align-items:flex-end}
.contacts {
padding:10px 13px;background:var(--glass);border:1px solid #ffffff30;border-radius:13px;font-size:11px;font-weight:800;letter-spacing:.12em;backdrop-filter:blur(10px)}
.contact-dots {
display:flex;gap:5px;margin-top:6px}
.contact-dots i {
width:19px;height:5px;border-radius:8px;background:#ffffff4c}
.contact-dots i.hit {
background:#ff6e9d;box-shadow:0 0 12px #ff5b94}
.music-chip {
font-size:10px;letter-spacing:.08em;padding:9px 12px;border-radius:12px;background:var(--glass);border:1px solid #ffffff30;backdrop-filter:blur(10px);color:#fff}
.music-chip b {
color:#ffd47d}
.overlay {
position:fixed;z-index:5;inset:0;display:grid;place-items:center;padding:24px;background:linear-gradient(180deg,rgba(36,25,66,.08),rgba(27,22,59,.37));transition:opacity .35s}
.overlay.hidden {
opacity:0;pointer-events:none}
.panel {
width:min(440px,100%);text-align:center;padding:30px 28px 25px;border:1px solid #fff4;border-radius:28px;background:linear-gradient(145deg,rgba(48,36,81,.76),rgba(43,38,77,.61));backdrop-filter:blur(18px);box-shadow:0 24px 80px #1c143c50, inset 0 1px #ffffff25}
.eyebrow {
font-size:10px;font-weight:800;letter-spacing:.3em;color:#ffd293}
.logo {
font:700 clamp(46px,12vw,70px)/.95 'Space Grotesk';letter-spacing:-.075em;margin:12px 0 6px;text-shadow:0 5px 22px #ff758566}
.logo em {
font-style:normal;color:#ff8baa}
.tagline {
font-size:13px;color:#e4d8eb;letter-spacing:.07em;margin:0 0 21px}
.car-select {
display:flex;gap:10px;margin:0 auto 20px;max-width:330px}
.car-option {
flex:1;padding:12px;border-radius:16px;border:1px solid #fff3;background:#ffffff0b;color:#fff;cursor:pointer;font:600 12px 'DM Sans';transition:.2s}
.car-option.selected {
background:#ff83a62a;border-color:#ff91b5;box-shadow:0 0 0 1px #ff91b566}
.car-icon {
font-size:24px;display:block;margin-bottom:4px}
.primary {
border:0;border-radius:15px;padding:15px 25px;width:min(280px,100%);background:linear-gradient(110deg,#ff729d,#ffb076);color:#381f48;font:800 13px 'Space Grotesk';letter-spacing:.17em;cursor:pointer;box-shadow:0 9px 28px #ff73964a;transition:transform .15s,filter .15s}
.primary:active {
transform:scale(.97);filter:brightness(1.1)}
.instructions {
font-size:11px;line-height:1.55;color:#ddd2e8;margin:16px auto 0;max-width:290px}
.instruction-strong {
color:#fff;font-weight:700}
.tap-tip {
display:none;font-size:10px;color:#fff9;margin:10px 0 0}
.sound-toggle {
position:fixed;top:calc(env(safe-area-inset-top) + 15px);right:16px;z-index:7;border:1px solid #fff5;background:#34265088;color:#fff;border-radius:50px;padding:9px 13px;font-weight:700;font-size:11px;backdrop-filter:blur(10px);cursor:pointer}
body:has(#hud.active) .sound-toggle {
display:none}
.end-score {
font:700 38px 'Space Grotesk';margin:7px}
.end-caption {
font-size:10px;letter-spacing:.2em;color:#dbcce7}
.hidden-view {
display:none!important}
.loading {
position:fixed;inset:0;z-index:10;display:grid;place-items:center;background:#291e50;color:white;font:700 12px 'Space Grotesk';letter-spacing:.25em}
.loading.off {
display:none}
@media(max-width:500px) {
.panel {
padding:26px 19px 22px}
.hud {
padding-left:14px;padding-right:14px}
.pill {
min-width:64px;padding:7px 9px}
.pill strong {
font-size:16px}
.tap-tip {
display:block}
}
@media(orientation:landscape) and (max-height:520px) {
.panel {
padding:16px 24px}
.logo {
font-size:44px;margin:4px}
.tagline {
margin-bottom:10px}
.car-select {
margin-bottom:10px}
.instructions {
margin-top:8px}
}

